-- Contract rates (CR) master data: the nett rate per pax of every agent contract (run once in Supabase > SQL Editor > New query > Run).
-- Safe to run again; the first run also fills the table with the rates read from the contracts in the Contract Rate folder.
-- Requires booking-permissions.sql (has_section). Edit the rates in the app: Menu > Contract rates.
--
-- One row = one rate: agent + package + pax range + validity dates. The booking price is
-- rate per pax x pax of the row that fits the agent, package, tour date and number of pax.
-- Pax ranges follow the car rule (1 car = 3 guests + guide): 1-3 pax = the 2-pax rate, 4-6 = the 4-pax rate, 7+ = the 6-pax rate.
-- Agents whose contract states other ranges (ICS, Bintang, Fly Bali, Bhara: West, East, Combination) use 1-4 / 5-7 / 8+.

create table if not exists public.contract_rates (
  id uuid primary key default gen_random_uuid(),
  agent text not null,
  package text not null,
  pax_min integer not null default 1 check (pax_min >= 1),
  pax_max integer not null default 99 check (pax_max >= pax_min),
  rate_per_pax numeric not null check (rate_per_pax >= 0),
  valid_from date not null default date '2000-01-01',
  valid_to date,
  source text not null default '',
  note text not null default '',
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid() references auth.users(id)
);
create index if not exists contract_rates_agent_idx on public.contract_rates (agent, package);
alter table public.contract_rates enable row level security;

drop policy if exists contract_rates_read on public.contract_rates;
create policy contract_rates_read on public.contract_rates for select to authenticated
  using (public.has_section('accounting') or public.has_section('dashboard'));
drop policy if exists contract_rates_write on public.contract_rates;
create policy contract_rates_write on public.contract_rates for all to authenticated
  using (public.has_section('accounting')) with check (public.has_section('accounting'));
revoke all on public.contract_rates from anon;

do $seed$
begin
  if not exists (select 1 from public.contract_rates) then
  end if;
end
$seed$;
